// ComboBox of QtQuick.Templates. What is expected here is what Qt 6.11 noted
// and answered when a QtTest `TestCase` made the same moves in the same
// scene.
import { play } from "./moves.js";
import { test } from "./open.js";

test("a ComboBox has a current row, by its index or by its value, and says what the row's text and value are", async ({ page }) => {
  await play(page, "popupcombos", COMBOS);
});

test("the mouse, the keys and the wheel pick a row of a ComboBox, and what is typed into one is finished from its rows", async ({ page }) => {
  await play(page, "popupcombos", PICKED);
});

